import React from "react";

const pickups = [
{
id:1,
location:"Sector 4",
bin:"BIN-204",
time:"07:00 AM"
},
{
id:2,
location:"Zone B",
bin:"BIN-552",
time:"09:30 AM"
}
];

const ScheduleTab = () => {

return (

<div className="w-full max-w-[900px]">

<h2 className="text-5xl font-black italic text-[#47510B] mb-10">
Today's Pickups
</h2>

<div className="space-y-5">

{pickups.map((p)=>(
<div
key={p.id}
className="bg-white p-6 rounded-3xl shadow-lg flex justify-between items-center"
>

<div>

<p className="text-sm font-black text-[#A1AED1] uppercase">
{p.time}
</p>

<h3 className="text-2xl font-black text-[#47510B] italic">
{p.location}
</h3>

<p className="text-xs font-bold text-[#47510B]/60">
{p.bin}
</p>

</div>

<button className="bg-[#CAD23C] text-[#47510B] px-6 py-3 rounded-xl font-black">
COMPLETE
</button>

</div>
))}

</div>

</div>

);
};

export default ScheduleTab;
